/**
 * Generic function preserving exact element type T across calls
 */
function getFirstElement<T>(items: T[]): T | undefined {
  return items.length > 0 ? items[0] : undefined;
}

// TypeScript preserves specific types instead of falling back to any
const firstNumber = getFirstElement([10, 20, 30]); // Inferred as number | undefined
const firstWord = getFirstElement(["apple", "banana"]); // Inferred as string | undefined

console.log(firstNumber); // 10
console.log(firstWord);   // apple

interface HasLength {
  length: number;
}

function logLength<T extends HasLength>(item: T): number {
  console.log(`Length: ${item.length}`);
  return item.length;
}

// Valid invocations (strings and arrays possess a length property)
logLength("Hello TypeScript"); // Length: 16
logLength([1, 2, 3, 4, 5]);     // Length: 5

// INVALID: Numbers do not have a length property
// logLength(12345); 
// Error: Argument of type 'number' is not assignable to parameter of type 'HasLength'.

// 1. Union Type: Value can be one of multiple distinct types
type Status = "idle" | "loading" | "success" | "error";
let currentStatus: Status = "loading";

// 2. Intersection Type: Combines multiple shapes into a single required contract
interface Identifiable {
  id: string;
}

interface Timestamped {
  createdAt: Date;
  updatedAt: Date;
}

type DatabaseRecord = Identifiable & Timestamped;

const record: DatabaseRecord = {
  id: "rec_98234",
  createdAt: new Date(),
  updatedAt: new Date()
};

console.log(`Record ID: ${record.id}`);

type Direction = "NORTH" | "SOUTH" | "EAST" | "WEST";

function movePlayer(dir: Direction, steps: number): void {
  console.log(`Moving ${steps} steps towards ${dir}`);
}

movePlayer("NORTH", 5); // Valid

// INVALID: Typing error caught at compile-time!
// movePlayer("UP", 5);
// Error: Argument of type '"UP"' is not assignable to parameter of type 'Direction'.

function processInput(input: string | number | Date): string {
  // 1. Narrowing using typeof
  if (typeof input === "string") {
    return `String length: ${input.length}`;
  }

  if (typeof input === "number") {
    return `Fixed number: ${input.toFixed(2)}`;
  }

  // 2. Narrowing using instanceof
  if (input instanceof Date) {
    return `Formatted date: ${input.toISOString()}`;
  }

  return "Unknown input";
}

console.log(processInput("Hello")); // String length: 5
console.log(processInput(42.678));  // Fixed number: 42.68
console.log(processInput(new Date())); // Formatted date: ...

interface Circle {
  kind: "circle";
  radius: number;
}

interface Square {
  kind: "square";
  sideLength: number;
}

interface Rectangle {
  kind: "rectangle";
  width: number;
  height: number;
}

type Shape = Circle | Square | Rectangle;

function calculateArea(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      // Math formula approx: 3.14159 * r * r
      return 3.14159 * shape.radius * shape.radius;
    case "square":
      return shape.sideLength * shape.sideLength;
    case "rectangle":
      return shape.width * shape.height;
  }
}

console.log(calculateArea({ kind: "circle", radius: 5 }));
console.log(calculateArea({ kind: "square", sideLength: 4 }));
